alter table public.budgets add column archived_at timestamptz, add column deleted_at timestamptz;
-- Existing administrator-only RLS applies to creation and lifecycle updates.
create or replace function public.queue_budget_alerts() returns void language sql security definer set search_path=public as $$ insert into budget_alerts(workspace_id,project_id) select b.workspace_id,b.project_id from budgets b join time_entries t on t.project_id=b.project_id and t.workspace_id=b.workspace_id where t.billable and b.archived_at is null and b.deleted_at is null group by b.workspace_id,b.project_id,b.amount having sum(t.minutes/60.0*t.bill_rate)>=b.amount*0.8 on conflict do nothing $$;
create or replace function public.claim_budget_alerts(w uuid) returns table(name text,burn numeric,amount numeric) language plpgsql security definer set search_path=public,pg_temp as $$ begin if public.workspace_role(w) is distinct from 'owner' then raise exception 'Not authorized';end if;return query with claimed as(update budget_alerts set claimed=true where workspace_id=w and not claimed returning project_id) select p.name,sum(t.minutes/60.0*t.bill_rate),b.amount from claimed c join projects p on p.id=c.project_id and p.workspace_id=w join budgets b on b.project_id=p.id and b.workspace_id=w and b.archived_at is null and b.deleted_at is null join time_entries t on t.project_id=p.id and t.workspace_id=w and t.billable group by p.name,b.amount;end $$;
